// Helper functions for employee data
const EmployeesHelper = {
  getAll() {
    return EmployeesData;
  },

  getActive() {
    return EmployeesData.filter(e => e.status === 'Đang làm việc' || e.status === 'Thử việc');
  },

  getById(id) {
    return EmployeesData.find(e => e.id === id);
  },

  getByDepartment(deptId) {
    return EmployeesData.filter(e => e.department === deptId);
  },

  getByStatus(status) {
    return EmployeesData.filter(e => e.status === status);
  },

  getStats() {
    const active = this.getActive();
    const total = active.length;
    const trial = EmployeesData.filter(e => e.status === 'Thử việc').length;
    const resigned = EmployeesData.filter(e => e.status === 'Đã nghỉ việc').length;
    const retired = EmployeesData.filter(e => e.status === 'Nghỉ hưu').length;
    const male = active.filter(e => e.gender === 'Nam').length;
    const female = active.filter(e => e.gender === 'Nữ').length;
    const avgAge = Math.round(active.reduce((s, e) => s + Helpers.calcAge(e.birthDate), 0) / total);
    const totalPayroll = active.reduce((s, e) => s + e.p1 + e.p2 + e.p3 + e.allowances, 0);

    return { total, trial, resigned, retired, male, female, avgAge, totalPayroll };
  },

  getContractExpiring(days = 60) {
    const now = new Date();
    const threshold = new Date(now.getTime() + days * 86400000);
    return EmployeesData.filter(e => {
      if (!e.contractEnd || e.status !== 'Đang làm việc') return false;
      const end = new Date(e.contractEnd);
      return end <= threshold && end >= now;
    });
  },

  // ADD NEW EMPLOYEE
  addEmployee(data) {
    const newId = 'VNM-' + String(EmployeesData.length + 1).padStart(4, '0');
    const newEmp = {
      id: newId,
      ...data,
      history: [{
        date: new Date().toISOString().split('T')[0],
        type: 'Tuyển dụng mới',
        fromDept: '',
        toDept: data.department,
        fromPos: '',
        toPos: data.position,
        note: 'Tiếp nhận hồ sơ mới vào hệ thống'
      }]
    };
    EmployeesData.push(newEmp);
    return newEmp;
  },

  // UPDATE EMPLOYEE
  updateEmployee(id, data) {
    const emp = this.getById(id);
    if (emp) {
      Object.assign(emp, data);
      return true;
    }
    return false;
  },

  // TRANSFER EMPLOYEE
  transferEmployee(id, newDept, newPosition, note) {
    const emp = this.getById(id);
    if (!emp) return false;

    const oldDept = emp.department;
    const oldPos = emp.position;

    // Cập nhật thông tin hiện tại
    emp.department = newDept;
    emp.position = newPosition;

    // Tạo mảng history nếu chưa có
    if (!emp.history) emp.history = [];

    // Ghi log vào history
    emp.history.push({
      date: new Date().toISOString().split('T')[0],
      type: 'Thuyên chuyển',
      fromDept: oldDept,
      toDept: newDept,
      fromPos: oldPos,
      toPos: newPosition,
      note: note || 'Quyết định thuyên chuyển nội bộ'
    });

    return true;
  },

  // EXPORT TO JSON (BACKUP)
  backupData() {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(EmployeesData, null, 2));
    const dlAnchorElem = document.createElement('a');
    dlAnchorElem.setAttribute("href", dataStr);
    dlAnchorElem.setAttribute("download", `HRIS_Backup_${new Date().toISOString().split('T')[0]}.json`);
    dlAnchorElem.click();
  },

  // ADVANCED SEARCH (BY NAME, DEPT, AND HISTORY)
  search(query, status = 'All', department = 'All') {
    query = query.toLowerCase();
    return EmployeesData.filter(e => {
      // Check status
      if (status !== 'All' && e.status !== status) return false;
      
      // Check department (match current or history)
      let matchesDept = (department === 'All');
      if (!matchesDept) {
        if (e.department === department) matchesDept = true;
        // Search in history
        if (e.history && e.history.some(h => h.fromDept === department || h.toDept === department)) {
          matchesDept = true;
        }
      }
      if (!matchesDept) return false;

      // Check text query
      if (!query) return true;
      const textMatch = (
        e.name.toLowerCase().includes(query) ||
        e.id.toLowerCase().includes(query) ||
        e.position.toLowerCase().includes(query) ||
        (e.history && e.history.some(h => h.note && h.note.toLowerCase().includes(query)))
      );
      
      return textMatch;
    });
  }
};
